{
  "product_id": 2,
  "product_name": "KB 프리N통장",
  "items": [
    {
      "key": "product_name",
      "summary": "KB 프리N통장은 소득 입금에 따른 특별금리와 다양한 소득을 관리할 수 있는 인컴박스 혜택을 제공하는 입출금통장입니다.",
      "source_section_ids": [2928]
    },
    {
      "key": "product_type",
      "summary": "KB 프리N통장은 보통예금과 저축예금으로 구성된 입출금이 자유로운 예금입니다.",
      "benefit": "입출금이 자유로운 예금으로, 보통예금과 저축예금이 병행됩니다.",
      "source_section_ids": [868, 2933, 2934]
    },
    {
      "key": "product_feature",
      "summary": "소득 입금에 따른 특별금리와 다양한 소득을 관리할 수 있는 인컴박스 혜택을 제공하는 입출금통장입니다.",
      "source_section_ids": [2929]
    },
    {
      "key": "eligibility_target",
      "summary": "실명이 확인된 개인이 가입대상이며, 개인사업자와 서류미제출 임의단체도 가입 가능합니다.",
      "conditions": [
        {
          "text": "실명이 확인된 개인",
          "src": [870],
          "only_in": "특약"
        },
        {
          "text": "개인사업자 및 서류미제출 임의단체도 가입 가능",
          "src": [2931],
          "only_in": "상품설명서"
        }
      ],
      "condition_logic": "모두 충족해야 함",
      "source_section_ids": [870, 871, 872, 2931]
    },
    {
      "key": "eligibility_restriction",
      "summary": "비거주자는 가입이 불가하며, 공동명의로 가입할 수 없습니다.",
      "conditions": [
        {
          "text": "비거주자는 가입이 불가",
          "src": [872],
          "only_in": "특약"
        },
        {
          "text": "공동명의로 가입할 수 없음",
          "src": [2931],
          "only_in": "상품설명서"
        }
      ],
      "condition_logic": "모두 충족해야 함",
      "source_section_ids": [872, 2931]
    },
    {
      "key": "account_limit",
      "summary": "1인 1계좌만 가입 가능합니다.",
      "conditions": [
        {
          "text": "1인 1계좌만 가입 가능",
          "src": [871],
          "only_in": "특약"
        }
      ],
      "condition_logic": "모두 충족해야 함",
      "source_section_ids": [871, 2931]
    },
    {
      "key": "deposit_amount",
      "summary": "가입금액은 제한이 없습니다.",
      "source_section_ids": [2932]
    },
    {
      "key": "base_rate",
      "summary": "기본금리는 결산일 현재 지점 및 KB 국민은행 홈페이지에 게시한 예금과목별 기본금리를 적용합니다.",
      "source_section_ids": [877, 2938]
    },
    {
      "key": "event_special_rate",
      "summary": "특별금리는 결산기 평균잔액 200만원 이하 금액에 연 1.4%의 특별금리를 적용하며, 신규 가입일부터 1년 경과 후 처음 도래하는 결산일까지 적용됩니다.",
      "conditions": [
        {
          "text": "월 합산 50만원 이상 입금된 달이 최근 6개월 중 2개월 이상 (보통예금)",
          "src": [881],
          "only_in": "특약"
        },
        {
          "text": "월 합산 50만원 이상 입금된 달이 최근 3개월 중 1개월 이상 (저축예금)",
          "src": [881],
          "only_in": "특약"
        }
      ],
      "exceptions": [
        {
          "text": "신규 가입 후 처음 도래하는 결산일에는 조건 충족 여부에 관계없이 특별금리 적용",
          "src": [881],
          "only_in": "특약"
        }
      ],
      "special": {
        "text": "특별금리는 전환계좌의 경우 전환 후 처음 도래하는 결산일에는 전환 전 상품의 금리를 적용하고, 다음 결산기부터 이 통장의 금리를 적용합니다.",
        "src": [882]
      },
      "as_of": "2026.07.01",
      "doc_diff": "특약과 상품설명서에 특별금리 적용 조건 및 기간에 차이가 있음",
      "source_section_ids": [879, 880, 881, 2939, 2940, 2941, 2953]
    },
    {
      "key": "interest_payment",
      "summary": "보통예금의 이자는 매년 6, 12월의 둘째 금요일에 결산하여 다음날 원금에 더하며, 저축예금의 이자는 매년 2, 5, 8, 11월의 둘째 금요일에 결산하여 다음날 원금에 더합니다.",
      "conditions": [
        {
          "text": "이자는 이자지급을 제외한 최종 거래일부터 5년이 경과한 날부터는 원금에 더하지 않고, 계좌 해지 또는 추가 입출금 거래 발생일에 일괄 계산하여 지급할 수 있음",
          "src": [876],
          "only_in": "특약"
        }
      ],
      "source_section_ids": [875, 876, 2937]
    },
    {
      "key": "final_rate",
      "summary": "최종금리는 기본금리와 특별금리를 합한 금리로, 최저 연 0.1%~최고 연 1.5%까지 적용됩니다.",
      "source_section_ids": [2940]
    },
    {
      "key": "tax",
      "summary": "비과세종합저축으로 가입 가능하며, 관련 세법이 개정될 경우 세율이 변경되거나 세금이 부과될 수 있습니다.",
      "source_section_ids": [2944]
    },
    {
      "key": "transaction_restriction",
      "summary": "예금잔액이 10,000원 미만이며, 1년 이상 입출금 거래가 없는 계좌는 거래가 제한됩니다.",
      "conditions": [
        {
          "text": "예금잔액이 10,000원 미만이며, 1년 이상 입출금 거래가 없는 계좌",
          "src": [2949],
          "only_in": "상품설명서"
        },
        {
          "text": "예금잔액이 10,000원 이상 50,000원 미만이며, 2년 이상 입출금 거래가 없는 계좌",
          "src": [2949],
          "only_in": "상품설명서"
        },
        {
          "text": "예금잔액이 50,000원 이상 100,000원 미만이며, 3년 이상 입출금 거래가 없는 계좌",
          "src": [2949],
          "only_in": "상품설명서"
        }
      ],
      "condition_logic": "모두 충족해야 함",
      "source_section_ids": [2949]
    },
    {
      "key": "fee",
      "summary": "KB 국민은행 인터넷·모바일뱅킹 다른은행 이체수수료, 타행자동이체 수수료 등은 수수료면제 대상입니다.",
      "conditions": [
        {
          "text": "전월(1일~말일) 중 이 통장에서 50만원 이상 입금 이력이 있는 경우",
          "src": [884],
          "only_in": "특약"
        },
        {
          "text": "KB 리브모바일(KB Liiv M) 자동이체 출금 이력이 있는 경우",
          "src": [884],
          "only_in": "특약"
        }
      ],
      "special": {
        "text": "수수료 면제 기간은 이번달 11일부터 다음달 10일까지이며, 면제 횟수는 제한이 없습니다.",
        "src": [885, 886]
      },
      "source_section_ids": [884, 885, 886, 887, 2943]
    },
    {
      "key": "assignment_collateral",
      "summary": "양도는 가능하며, 질권설정 및 담보제공은 불가능합니다.",
      "conditions": [
        {
          "text": "질권설정 불가",
          "src": [2946],
          "only_in": "상품설명서"
        },
        {
          "text": "담보제공 불가",
          "src": [2947],
          "only_in": "상품설명서"
        }
      ],
      "source_section_ids": [2945, 2946, 2947]
    },
    {
      "key": "partner_benefit",
      "summary": "다양한 소득 입금 내역을 한 눈에 확인할 수 있는 인컴박스 혜택을 제공합니다.",
      "source_section_ids": [2942]
    },
    {
      "key": "product_conversion",
      "summary": "다른 상품에서 이 통장으로 전환한 경우, 전환 후 처음 도래하는 결산기에는 전환 전 상품의 금리를 적용하고, 다음 결산기부터 이 통장의 금리를 적용합니다.",
      "conditions": [
        {
          "text": "전환 후 처음 도래하는 결산기에는 전환 전 상품의 금리를 적용",
          "src": [882],
          "only_in": "특약"
        },
        {
          "text": "특별금리는 전환 후 처음 도래하는 결산일부터 최초 전환일 기준 1년 경과 후 처음 도래하는 결산일까지 적용",
          "src": [2953],
          "only_in": "상품설명서"
        }
      ],
      "source_section_ids": [882, 2936, 2939, 2941, 2953]
    }
  ]
}

